}
?>
<section class="pagehero"><div class="container"><h1>Sell Your Property</h1><p>Submit your property details and our team will contact you.</p></div></section><section class="section"><div class="container grid2"><form class="form-card" method="post"><h2 style="color:var(--navy);margin-bottom:20px">List Property</h2><?php if($msg):?><div class="message"><?=$msg?></div><br><?php endif;?><div class="formgrid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input name="email" type="email" required></div><div><label>Phone</label><input name="phone" required></div><div><label>Property Type</label><select name="type"><option>House</option><option>Apartment</option><option>Villa</option><option>Commercial</option><option>Plot</option></select></div><div class="full"><label>Property Title</label><input name="property_title" required></div><div><label>City</label><input name="city" required></div><div><label>Expected Price</label><input name="price" required></div><div class="full"><label>Address</label><input name="address" required></div><div class="full"><button class="btn gold">Submit Listing</button></div></div></form><div><h2 style="color:var(--navy);font-size:36px">Professional property listing</h2><p class="muted">Your request is stored in the MySQL enquiries table for the admin to review.</p></div></div></section><?php include 'includes/footer.php'; ?></body></html>